            JavaScript

    <script>

// javascript program to print
// sierpinski triangle.

function printSierpinski(n)
{
    for (var y = n - 1; y >= 0; y--) {

        // printing space till
        // the value of y
        for (var i = 0; i < y; i++) {
            document.write("&nbsp;");
        }

        // printing '*'
        for (var x = 0; x + y < n; x++) {

            // printing '*' at the appropriate
            // position is done by the and 
            // value of x and y wherever value
            // is 0 we have printed '*'
            if ((x & y) != 0)
                document.write("&nbsp;&nbsp;&nbsp;");
            else
                document.write("*&nbsp;");
        }

        document.write("<br>");
    }
}

// Driver code
var n = 16;

// Function calling
printSierpinski(n);


